func consume(session sarama.ConsumerGroupSession, msg *sarama.ConsumerMessage) error {
    if err := processMessage(msg); err != nil {
        log.Error("failed to process", "err", err, "offset", msg.Offset)
        return err // never committed → redelivered forever, partition blocked
    }
    session.MarkMessage(msg, "")
    return nil
}
